// Provider holds the preset configuration for a known LLM provider.
//
// Protocol uses the canonical names defined in protocol.go:
//   - ProtocolAnthropic ("anthropic")
//   - ProtocolOpenAIChatCompletions ("openai")
//   - ProtocolOpenAIResponses ("openai-responses")
//   - ProtocolAnthropicBedrock ("anthropic-bedrock")
//
// To add a built-in provider that speaks a different protocol, set Protocol
// accordingly and ensure NewLLMClient has a matching case.

func NewLLMClient(ep ResolvedEndpoint, collector *RetryCollector, raw *RawHolder) LLMClient {
	cfg := ClientConfig{
		URL:            ep.URL,
		APIKey:         ep.Token,
		Model:          ep.Model,
		AuthHeader:     ep.AuthHeader,
		Timeout:        ep.Timeout,
		ExtraBody:      ep.ExtraBody,
		ExtraHeaders:   ep.ExtraHeaders,
		RetryCodes:     ep.RetryCodes,
		retryCollector: collector,
		rawHolder:      raw,
		AWSProfile:     ep.AWSProfile,
		AWSRegion:      ep.AWSRegion,
	}
	switch ep.Protocol {
	case ProtocolAnthropic:
		return NewAnthropicClient(cfg)
	case ProtocolAnthropicBedrock:
		return NewAnthropicBedrockClient(cfg)
	case ProtocolOpenAIResponses:
		return NewOpenAIResponsesClient(cfg)
	default:
		return NewOpenAIClient(cfg)
	}

